/* TB_MAIL_AI_ANALYSIS INSERT mail.insertMailAiAnalysis */
INSERT INTO TB_MAIL_AI_ANALYSIS (
    MAIL_ID, MAIL_PURPOSE_CD, ACTION_REQUIRED_CD,
    URGENCY_CD, IMPORTANCE_CD, WORK_CATEGORY_CD,
    DUE_DT, SUMMARY, ACTION_COMPLETE_YN, ANALYZED_DT
) VALUES (
    #{mailId}, #{mailPurposeCd}, #{actionRequiredCd},
    #{urgencyCd}, #{importanceCd}, #{workCategoryCd},
    #{dueDt}, #{summary}, 'N', NOW()
)

